document.addEventListener('keydown',event=>{if(event.target.matches('[role=tab]')&&['ArrowLeft','ArrowRight','Home','End'].includes(event.key)){event.preventDefault();const tabs=$$('[role=tab]'),i=tabs.indexOf(event.target),next=event.key==='Home'?0:event.key==='End'?tabs.length-1:(i+(event.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length;tabs[next].click();tabs[next].focus()}if(event.key==='Escape'&&activeTask)closeModal();if(['Enter',' '].includes(event.key)&&event.target.matches('[data-task],[data-agent]')){event.preventDefault();event.target.click()}if(event.key==='Tab'&&activeTask){const focusable=$$('.modal button,.modal a,.modal select,.modal textarea').filter(e=>!e.disabled&&e.offsetParent!==null),first=focusable[0],last=focusable.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last?.focus()}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first?.focus()}}});
