let artifactInfo=null,artifactRequest=0,vmEvidenceRequest=0;
async function loadArtifacts(id,version=messageViewVersions.get(id)){
 if(!id||activeTask!==id||messageViewVersions.get(id)!==version)return;
 const request=++artifactRequest,task=state.tasks.find(t=>t.id===id)||workTasks.find(t=>t.id===id);
 if(!task||plan(task).unavailable)return;
 const current=()=>activeTask===id&&messageViewVersions.get(id)===version&&request===artifactRequest;
 try{const result=await api('/api/artifacts?'+new URLSearchParams({task:id}));if(!current())return;artifactInfo=result}catch(error){if(!current())return;artifactInfo={task_id:id,error:true,message:error.message,files:[]}}
 renderModal();
}
function artifactActions(task){
 if(!artifactInfo||artifactInfo.task_id!==task.id)return '<span class="small-text muted">결과 파일 확인 중…</span>';
 if(artifactInfo.error)return `<span class="small-text muted">${esc(artifactInfo.message||'결과 파일을 확인하지 못했습니다.')}</span><button class="text-button" data-action="refresh-artifacts">다시 확인 ↻</button>`;
 const names=new Set(artifactInfo.files.map(f=>f.name)),links=[];
 const outputs=artifactInfo.files.filter(f=>f.kind==='deliverable'||f.name.startsWith('deliverables/'));
 for(const file of outputs){const href='/api/artifact?'+new URLSearchParams({task:task.id,file:file.name});const label=file.name.endsWith('/report.html')?'리서치 보고서 (HTML)':file.name.endsWith('/report.md')?'보고서 원문 (MD)':file.name.endsWith('/image.jpg')||file.name.endsWith('/image.png')?'사진 보기':file.label||file.name.split('/').pop();links.push(`<a class="button small" target="_blank" href="${esc(href)}">${esc(label)} ↗</a>`)}
 if(!outputs.length)for(const name of ['workspace/research/image.jpg','workspace/research/image.png'])if(names.has(name))links.push(`<a class="button small" target="_blank" href="/api/artifact?task=${encodeURIComponent(task.id)}&file=${encodeURIComponent(name)}">사진 보기 ↗</a>`);
 if(outputs.length>1&&names.has('results.zip'))links.push(`<a class="button subtle small" href="/api/artifact?task=${encodeURIComponent(task.id)}&file=results.zip">결과 파일만 묶어 받기 ↓</a>`);
 if(technical&&names.has('artifacts.zip'))links.push(`<a class="text-link" href="/api/artifact?task=${encodeURIComponent(task.id)}&file=artifacts.zip">내부 실행 기록 ZIP ↓</a>`);
 if(technical&&names.has('report.md'))links.push(`<a class="text-link" target="_blank" href="/api/artifact?task=${encodeURIComponent(task.id)}&file=report.md">실행 보고서 ↗</a>`);
 if(technical&&names.has('report.json'))links.push(`<a class="text-link" target="_blank" href="/api/artifact?task=${encodeURIComponent(task.id)}&file=report.json">검증 기록 JSON ↗</a>`);
 return links.join('')||'<span class="small-text muted">현재 읽을 수 있는 결과 파일이 없습니다. 기록과 저장소를 확인해 주세요.</span>';
}
