// Small local SVG parts: no remote avatar service or image generation dependency.
const officeSkin=['#f2cfb3','#dba77e','#b87c58','#82513b'],officeShirt=['#cf765f','#829987','#8598b2','#c6a065','#a394b3','#5e777e'];
let officeSelected=null,officeDraft=null,officeReturnFocus=null;
function officeLook(id,index=0){return state.office_appearance?.[id]||{hair:index%4,skin:index%4,shirt:index%6,accessory:index%3}}
function officeCharacter(look,facing='front'){
 const skin=officeSkin[look.skin]||officeSkin[0],shirt=officeShirt[look.shirt]||officeShirt[0],side=facing==='left'||facing==='right',back=facing==='back';
 const hair=['M25 35Q17 8 39 10Q62 8 55 36L48 23Q36 31 25 25Z','M23 47V25Q23 8 40 10Q59 10 57 30V48L49 44V27Q36 33 29 24V44Z','M24 31Q17 17 29 17Q29 7 40 12Q51 6 55 20Q63 24 56 35L48 24L27 29Z','M22 30Q21 9 41 10Q59 12 57 31L51 25H28Z'][look.hair]||'M22 30Q21 9 41 10Q59 12 57 31L51 25H28Z';
 let head=back?`<ellipse cx="40" cy="32" rx="17" ry="20" fill="${skin}"/><path d="M23 34V26Q22 9 40 10Q59 9 57 30V${look.hair===1?49:39}Q40 ${look.hair===1?56:52} 23 ${look.hair===1?49:39}Z" fill="#4b3934"/>`:side?`<ellipse cx="42" cy="33" rx="13" ry="19" fill="${skin}"/><path d="M53 31 59 36 53 38" fill="${skin}"/><path d="${look.hair===1?'M27 49V25Q25 10 42 11Q58 10 54 27L48 22 34 27V49Z':look.hair===2?'M28 34Q20 28 27 21Q25 11 36 13Q43 6 48 14Q59 13 55 27L48 22 34 28V39Z':'M29 35Q21 13 39 11Q56 8 54 27L48 22 33 28 33 40Z'}" fill="#4b3934"/><ellipse cx="33" cy="36" rx="3" ry="5" fill="${skin}"/><circle cx="49" cy="33" r="1.5" fill="#493a34"/><path d="M49 43h4" stroke="#9b6555" stroke-width="1.4"/>`:`<ellipse cx="40" cy="33" rx="17" ry="20" fill="${skin}"/><path d="${hair}" fill="#4b3934"/><g class="person-eyes" fill="#493a34"><circle cx="34" cy="35" r="1.6"/><circle cx="46" cy="35" r="1.6"/></g><path d="M37 43Q40 45 43 43" stroke="#9b6555" stroke-width="1.5" fill="none"/>`;
 if(look.accessory===1&&!back)head+=side?'<rect x="44" y="29" width="11" height="10" rx="3" fill="none" stroke="#514b4b" stroke-width="1.7"/>':'<g fill="none" stroke="#514b4b" stroke-width="1.7"><rect x="27" y="30" width="12" height="10" rx="4"/><rect x="41" y="30" width="12" height="10" rx="4"/><path d="M39 34H41"/></g>';
 if(look.accessory===2)head+='<path d="M21 34V25Q21 7 40 7Q59 7 59 25V34" fill="none" stroke="#677e77" stroke-width="4"/>';
 return `<svg class="office-person" data-view="${facing}" viewBox="0 0 80 104" aria-hidden="true"><ellipse cx="40" cy="98" rx="23" ry="4" fill="#483c32" opacity=".1"/><g ${facing==='left'?'transform="translate(80 0) scale(-1 1)"':''}><g class="person-legs" fill="#514d52"><rect class="person-leg-left" x="${side?32:28}" y="75" width="10" height="21" rx="4"/><rect class="person-leg-right" x="${side?42:43}" y="75" width="10" height="21" rx="4"/></g><g class="person-body"><path class="person-torso" d="${side?'M30 60Q30 50 40 50Q53 50 53 62L51 81H30Z':'M22 62Q23 50 39 50Q57 50 59 63L57 81H24Z'}" fill="${shirt}"/><path class="person-arm-left" d="${side?'M34 60 31 75':'M23 60 18 75'}" stroke="${skin}" stroke-width="8" stroke-linecap="round"/><path class="person-arm-right" d="${side?'M47 60 51 75':'M57 60 62 75'}" stroke="${skin}" stroke-width="8" stroke-linecap="round"/><g class="person-head"><rect x="34" y="44" width="12" height="13" rx="5" fill="${skin}"/>${head}</g></g></g></svg>`;
}

