function renderOfficeChat(data){renderPeerScores(data.scores);officeChatRows=data.messages;const area=$('#officeChatMessages');if(!area)return;const nearBottom=area.scrollHeight-area.scrollTop-area.clientHeight<70;area.innerHTML=data.messages.map(m=>`<div class="office-chat-message ${m.role==='user'?'from-user':'from-agent'}"><small>${m.role==='user'?'나':esc(state.team.agents.find(a=>a.id===data.agent_id)?.name||'팀원')}</small><p>${m.state==='queued'||m.state==='running'?'<span class="office-answering">답변을 생각하고 있어요…</span>':esc(m.error||m.content)}</p>${m.reply_to?.startsWith('task:')?`<button class="text-button" data-task="${esc(m.reply_to.slice(5))}">작업 확인 →</button><div data-office-media-task="${esc(m.reply_to.slice(5))}"></div>`:''}</div>`).join('')||'<div class="office-chat-empty">가볍게 말을 걸어보세요.<br><small>Slack을 열지 않고 여기서 바로 이야기합니다.</small></div>';fillOfficeMedia(data);if(nearBottom||!area.dataset.initial){area.scrollTop=area.scrollHeight;area.dataset.initial='1'}const waiting=data.messages.some(m=>['queued','running'].includes(m.state));$('[data-office-send]').disabled=waiting||officeChatSending;$('[data-office-work]').disabled=officeChatSending;$('#officeChatStatus').textContent=waiting?'팀원이 답변 중입니다. 다른 화면을 보셔도 대화는 유지됩니다.':'이 대화는 모아 안에만 기록됩니다.'}
async function loadOfficeChat(id,version){if(officeSelected!==id||officeChatVersion!==version||!$('#officeDialog')?.open)return;const data=await api('/api/office/chat?agent_id='+encodeURIComponent(id));if(officeSelected!==id||officeChatVersion!==version||!$('#officeDialog')?.open)return;renderOfficeChat(data);clearTimeout(officeChatTimer);officeChatTimer=setTimeout(()=>busy(null,()=>loadOfficeChat(id,version)),2500)}
async function sendOfficeChat(work=false){const id=officeSelected,version=officeChatVersion,text=$('#officeChatText').value.trim();if(!text)throw Error(work?'맡길 일을 입력해 주세요.':'말씀하실 내용을 입력해 주세요.');const signature=JSON.stringify([id,text,work]);let sent=officeRequests.get(id);if(!sent||sent.signature!==signature){sent={signature,key:crypto.randomUUID()};officeRequests.set(id,sent)}officeChatSending=true;$('[data-office-send]').disabled=true;$('[data-office-work]').disabled=true;try{const result=await api(work?'/api/office/task':'/api/office/chat',{agent_id:id,content:text,request_key:sent.key});officeRequests.delete(id);officeChatDrafts.set(id,'');if(officeSelected===id&&officeChatVersion===version){if($('#officeChatText').value.trim()===text)$('#officeChatText').value='';renderOfficeChat(result)}if(work)await refresh();}finally{officeChatSending=false;if(officeSelected===id&&officeChatVersion===version){$('[data-office-send]').disabled=officeChatRows.some(m=>['queued','running'].includes(m.state));$('[data-office-work]').disabled=false}}}
async function uploadTeamPhoto(input){const file=input.files?.[0],aid=input.dataset.teamPhoto;if(!file)return;if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>8*1024*1024)throw Error('8MB 이하 PNG·JPEG·WebP 사진을 선택하세요.');const url=URL.createObjectURL(file);try{const picture=await new Promise((resolve,reject)=>{const img=new Image();img.onload=()=>resolve(img);img.onerror=()=>reject(Error('사진을 읽지 못했습니다.'));img.src=url});if(picture.width>10000||picture.height>10000)throw Error('사진 크기는 10000px 이하로 선택하세요.');const canvas=document.createElement('canvas');canvas.width=512;canvas.height=512;const ctx=canvas.getContext('2d'),side=Math.min(picture.width,picture.height);ctx.drawImage(picture,(picture.width-side)/2,(picture.height-side)/2,side,side,0,0,512,512);state.agent_profiles=await api('/api/team/profile',{agent_id:aid,image_base64:canvas.toDataURL('image/png').split(',')[1]});renderEditors();renderHome();notify('프로필 사진을 저장했습니다. 연결된 Slack에도 자동 반영합니다.')}finally{URL.revokeObjectURL(url)}}
document.addEventListener('change',event=>{if(event.target.dataset.teamPhoto)busy(null,()=>uploadTeamPhoto(event.target))});
document.addEventListener('click',event=>{const b=event.target.closest('[data-office-send],[data-office-work],[data-connect-person]');if(!b)return;if(b.hasAttribute('data-office-send')||b.hasAttribute('data-office-work')){busy(null,()=>sendOfficeChat(b.hasAttribute('data-office-work')));return}busy(b,async()=>{const result=await api('/api/slack/auto',{action:'add',agent_id:b.dataset.connectPerson,team_id:$('#slackAutoWorkspace').value});renderSlackAuto(result);if(result.auth_command)$('.slack-workspace-auth').open=true})});
document.addEventListener('input',event=>{if(event.target.id==='officeChatText')rememberOfficeChat()});
document.addEventListener('keydown',event=>{if(event.target.id==='officeChatText'&&event.key==='Enter'&&(event.ctrlKey||event.metaKey)){event.preventDefault();busy(null,()=>sendOfficeChat())}});
document.addEventListener('click',event=>{
 const t=event.target.closest('[data-office-agent],[data-office-close],[data-office-random],[data-office-save],[data-action="office-customize"]');if(!t)return;
 if(t.dataset.officeAgent){openOfficeAgent(t.dataset.officeAgent);return}
 if(t.hasAttribute('data-office-close')){$('#officeDialog').close();return}
 if(t.dataset.action==='office-customize'){const first=state.team?.agents?.[0];if(first){openOfficeAgent(first.id);$('.office-customizer').open=true}return}
 if(t.hasAttribute('data-office-random')){for(const [key,max] of Object.entries({hair:4,skin:4,shirt:6,accessory:3})){officeDraft[key]=crypto.getRandomValues(new Uint32Array(1))[0]%max;$(`[data-office-part="${key}"]`).value=officeDraft[key]}$('#officePreview').innerHTML=officeCharacter(officeDraft);return}
 if(t.hasAttribute('data-office-save')){const id=officeSelected,value={...officeDraft};busy(t,async()=>{state.office_appearance=await api('/api/office/appearance',{agent_id:id,appearance:value});renderOffice(state.team.agents);if(officeSelected===id)$('#officeSaveStatus').textContent='저장했습니다.'});}
});
document.addEventListener('change',event=>{const t=event.target;if(t.dataset.officePart){officeDraft[t.dataset.officePart]=Number(t.value);$('#officePreview').innerHTML=officeCharacter(officeDraft);$('#officeSaveStatus').textContent='변경 내용을 저장해 주세요.'}});
let surveyInstallSelectionLoaded=false;
let resourceData=null,resourceTab='programs',resourceFilter='all',resourceQuery='',resourceSelection=new Set(),resourceTimer=null,resourceDrafts=new Map(),resourceSkillDraft=null;
const resourceJobLabels={queued:'설치 대기',running:'설치 중',completed:'확인 완료',failed:'설치 실패',interrupted:'결과 확인 필요',approval_required:'허용 필요',action_required:'준비 필요'};
function resourceIcon(id){return `<img class="resource-icon" src="/resource-icons/${esc(id||'skill')}.svg" alt="" loading="lazy">`}
function installResourceUI(){
 const nav=document.createElement('a');nav.href='#resources';nav.dataset.page='resources';nav.setAttribute('aria-label','도구와 스킬');nav.innerHTML=icon('layers')+'<span>도구와 스킬</span>';$('.sidebar nav').insertBefore(nav,$('.sidebar [data-page="docs"]'));
 const page=document.createElement('section');page.id='page-resources';page.className='page';page.hidden=true;page.innerHTML=`<div class="page-heading"><div><p class="eyebrow">READY TO WORK</p><h1>일에 필요한 준비를 한곳에서.</h1><p class="lead">프로그램, 스킬, 팀의 지시 사항을 관리하세요.</p></div><div class="survey-entry"><button class="text-button" data-survey-open>맞춤 추천 다시 받기</button><button class="button subtle small" data-resource-action="refresh">설치 목록 새로 확인 ↻</button></div></div><div id="resourceSummary" class="resource-summary"></div><div class="resource-tabs" role="tablist" aria-label="도구 관리"><button role="tab" data-resource-tab="programs">프로그램</button><button role="tab" data-resource-tab="skills">스킬</button><button role="tab" data-resource-tab="instructions">지시 사항</button></div><div id="resourcePanel"></div><section class="card resource-jobs"><div class="section-heading"><h2>설치·봇 요청 기록</h2><span class="muted small-text">설치 후 근거를 다시 확인합니다</span></div><div id="resourceJobs"></div></section>`;$('#main').append(page);

 const preflight=document.createElement('div');preflight.className='resource-preflight';preflight.innerHTML='<button class="text-button" data-resource-action="preflight">필요한 프로그램·스킬 미리 보기 ↗</button><div id="taskPreparation" hidden></div>';$('#composerPreparation').append(preflight);
}
function rememberResourceDraft(){if(resourceTab==='instructions'&&$('#resourceGlobal'))resourceDrafts.set('instructions',{global:$('#resourceGlobal').value,agents:Object.fromEntries($$('[data-resource-instructions]').map(el=>[el.dataset.resourceInstructions,el.value]))});if($('#resourceAutoPrograms'))resourceDrafts.set('policy',readResourcePolicy());if($('#skillName')&&!$('#resourceSkillEditor').hidden)resourceSkillDraft={id:$('#skillEditId').value,name:$('#skillName').value,description:$('#skillDescription').value,instructions:$('#skillInstructions').value,agents:$$('[data-skill-agent]:checked').map(x=>x.dataset.skillAgent)}}
async function loadResources(force=false){
 if(force)rememberResourceDraft();
 resourceData=await api('/api/resources/snapshot',{refresh:force});if(!surveyInstallSelectionLoaded){const saved=setup?.onboarding?.saved;if(saved?.state==='completed')resourceSelection=new Set((saved.programs||[]).filter(id=>{const p=resourceData.programs.find(p=>p.id===id);return p&&!p.installed&&!p.manual}));surveyInstallSelectionLoaded=true}renderResources();clearTimeout(resourceTimer);resourceTimer=setTimeout(()=>busy(null,updateResourceJobs),4000);
}
async function updateResourceJobs(){if(!location.hash.startsWith('#resources'))return;const previous=resourceData,next=await api('/api/resources/snapshot',{});const programChanged=JSON.stringify([previous.programs,previous.jobs,previous.guest])!==JSON.stringify([next.programs,next.jobs,next.guest]);const skillChanged=JSON.stringify(previous.skills)!==JSON.stringify(next.skills);if(skillChanged&&resourceTab==='skills')rememberResourceDraft();resourceData=next;if(skillChanged&&resourceTab==='skills')renderResources();else{renderResourceSummary();renderResourceJobs();if(resourceTab==='programs'&&programChanged){renderProgramCards();renderGuestResources()}}resourceTimer=setTimeout(()=>busy(null,updateResourceJobs),4000)}
function renderResourceSummary(){const d=resourceData;$('#resourceSummary').innerHTML=`<div><strong>${d.programs.filter(p=>p.installed).length}<small> / ${d.programs.length}</small></strong><span>현재 PC의 카탈로그 프로그램 설치됨</span></div><div><strong>${d.skills.filter(s=>s.installed).length}</strong><span>추가한 스킬</span></div><div><strong>${d.jobs.filter(j=>['approval_required','action_required'].includes(j.state)).length}</strong><span>확인할 설치 요청</span></div><p>이 PC · Windows<br><small>최근 확인 ${esc(new Date(d.checked_at*1000).toLocaleTimeString('ko-KR'))}</small></p>`}
function renderResources(){if(!resourceData)return;renderResourceSummary();$$('[data-resource-tab]').forEach(el=>{el.setAttribute('aria-selected',String(el.dataset.resourceTab===resourceTab));el.tabIndex=el.dataset.resourceTab===resourceTab?0:-1});const panel=$('#resourcePanel');
 if(resourceTab==='programs'){
 panel.innerHTML=`<div class="resource-tools"><label class="search-box"><input id="resourceSearch" type="search" aria-label="프로그램 검색" placeholder="프로그램 이름·용도 검색" value="${esc(resourceQuery)}"></label><div class="segmented"><button data-resource-filter="all" class="${resourceFilter==='all'?'selected':''}">전체</button><button data-resource-filter="installed" class="${resourceFilter==='installed'?'selected':''}">설치됨</button><button data-resource-filter="missing" class="${resourceFilter==='missing'?'selected':''}">미설치</button></div></div><p class="field-note">무료 기능만 사용합니다. 유료 구독·API·에셋 구매·체험판 전환은 진행하지 않습니다. 조건부 무료 항목은 사용 조건 확인이 필요합니다. PC와 VM의 설치 상태는 별개입니다. 설치는 사용자 범위로 실행하며 관리자 권한은 자동 요청하지 않습니다.</p><div id="resourcePrograms" class="resource-grid"></div><div class="resource-install-bar"><span id="resourceSelectedCount"></span><button class="button small" data-resource-action="install-selected">선택한 프로그램 설치</button></div>${resourcePolicyForm()}<details class="card resource-installed"><summary>이 PC에 등록된 주요 프로그램 <span>${resourceData.installed.length}개</span></summary><label><span class="sr-only">설치된 프로그램 검색</span><input id="installedSearch" type="search" placeholder="설치된 프로그램 검색"></label><div id="installedPrograms"></div></details>`;
 renderProgramCards();renderInstalledPrograms();renderGuestResources();
 }else if(resourceTab==='skills'){
 panel.innerHTML=`<div class="resource-section-intro"><div><h2>팀이 사용할 수 있는 스킬</h2><p class="field-note">스킬 추가는 무료이며, 외부 유료 기능 사용은 허용하지 않습니다. 스킬은 작업 방법과 검증 기준을 담은 지침입니다. 프로그램이나 새 도구 권한을 설치하는 기능과는 구분됩니다.</p></div><button class="button subtle small" data-resource-action="new-skill">내 스킬 추가 +</button></div><div class="resource-grid">${resourceData.skills.map(s=>`<article class="resource-card">${resourceIcon(s.icon)}<div class="resource-card-head"><h3>${esc(s.name)}</h3><span class="resource-state ${s.installed?'installed':''}">${s.installed?'추가됨':'추가 가능'}</span></div><p>${esc(s.description)}</p><small>${s.agents?.length?s.agents.map(id=>esc(state.team.agents.find(a=>a.id===id)?.name||id)).join(' · '):'모든 팀원'} · ${s.builtin?'기본 제공':'내 스킬'}</small><div class="resource-card-actions"><button class="text-button" data-resource-action="edit-skill" data-skill-id="${esc(s.id)}">내용·배정</button><button class="button subtle small" data-resource-action="toggle-skill" data-skill-id="${esc(s.id)}">${s.installed?'사용 중지':'추가'}</button></div></article>`).join('')}</div>${resourcePolicyForm()}<section class="card resource-skill-editor" id="resourceSkillEditor" hidden><h2>스킬 편집</h2><input id="skillEditId" type="hidden"><div class="form-grid"><label>스킬 이름<input id="skillName" maxlength="60"></label><label>짧은 설명<input id="skillDescription" maxlength="300"></label></div><label>스킬 지침<textarea id="skillInstructions" maxlength="12000" rows="7" placeholder="무엇을, 어떤 순서와 기준으로 수행해야 하는지 적어 주세요."></textarea></label><label class="resource-file">Markdown 파일에서 불러오기<input type="file" id="skillMarkdown" accept=".md,.txt,text/markdown,text/plain"></label><fieldset class="resource-agent-picks"><legend>사용할 팀원 · 선택하지 않으면 모두 사용</legend>${(state.team.agents||[]).map(a=>`<label><input type="checkbox" data-skill-agent="${esc(a.id)}">${esc(a.name)}</label>`).join('')}</fieldset><button class="button small" data-resource-action="save-skill">스킬 저장</button><p id="skillSaveStatus" role="status" class="field-note"></p></section>`;
 if(resourceSkillDraft)showSkillEditor(resourceSkillDraft);
 }else{
 const draft=resourceDrafts.get('instructions');panel.innerHTML=`<section class="card resource-instructions"><div class="section-heading"><h2>전역 지시 사항</h2><span class="muted small-text">새 작업부터 적용</span></div><p class="field-note">모든 팀원에게 공통으로 전달할 기준입니다. 진행 중인 작업에는 접수 당시 지침이 유지됩니다.</p><label><span class="sr-only">전역 지시 사항</span><textarea id="resourceGlobal" data-revision="${resourceData.policy.updated||0}" maxlength="12000" rows="6" placeholder="예: 한국어 존댓말로 보고하고, 실행한 근거를 남겨 주세요.">${esc(draft?.global??resourceData.policy.global_instructions)}</textarea></label><button class="button small" data-resource-action="save-global">전역 지침 저장</button><p id="globalSaveStatus" class="field-note" role="status"></p></section><section class="card resource-instructions"><div class="section-heading"><h2>봇별 지시 사항</h2><a class="text-link" href="#settings/team">이름·역할 설정 ↗</a></div>${(setup?.team.agents||[]).map(a=>`<label class="resource-agent-instruction"><b>${esc(a.name)}</b><small>${esc(a.capabilities.map(r=>roles[r]).join(' · '))}</small><textarea data-resource-instructions="${esc(a.id)}" maxlength="2000" rows="4" placeholder="이 팀원에게만 전달할 지시 사항">${esc(draft?.agents?.[a.id]??a.instructions)}</textarea></label>`).join('')}<button class="button small" data-resource-action="save-agent-instructions">봇별 지침 저장</button><p id="agentInstructionStatus" class="field-note" role="status"></p></section>`;
 }
 renderResourceJobs();
}
function resourcePolicyForm(){const p=resourceDrafts.get('policy')||resourceData.policy;return `<details class="card resource-policy" data-revision="${p.updated||0}"><summary>봇 자동 준비 설정</summary><p class="field-note">봇이 필요한 프로그램이나 스킬을 요청하면 아래 설정을 확인해 처리합니다. 목록 밖의 프로그램·임의 설치 명령은 실행하지 않습니다.</p><label class="check-row"><input id="resourceAutoPrograms" type="checkbox" ${p.auto_programs?'checked':''}>허용한 프로그램은 봇이 자동 설치</label><div class="resource-allowlist">${resourceData.programs.filter(a=>!a.manual).map(a=>`<label><input type="checkbox" data-resource-allow="${a.id}" ${p.allowed_programs.includes(a.id)?'checked':''}>${resourceIcon(a.icon)}${esc(a.name)}</label>`).join('')}</div><label class="check-row"><input id="resourceAutoSkills" type="checkbox" ${p.auto_skills?'checked':''}>등록된 스킬은 봇이 필요할 때 추가</label><label class="check-row"><input id="resourcePackageTerms" type="checkbox" ${p.package_terms?'checked':''}>선택한 프로그램의 <a href="https://learn.microsoft.com/en-us/windows/package-manager/winget/install" target="_blank" rel="noopener">설치·라이선스 조건</a>을 확인했으며 설치 시 적용에 동의합니다.</label><label class="check-row"><input id="resourceSourceTerms" type="checkbox" ${p.source_terms?'checked':''}>WinGet 저장소 이용 조건을 확인하고 적용에 동의합니다.</label><p class="field-note">각 프로그램 카드의 공식 사이트에서 라이선스를 확인하세요. 자동 재부팅과 관리자 권한 승격은 하지 않습니다.</p><button class="button small" data-resource-action="save-policy">자동 준비 설정 저장</button><p id="resourcePolicyStatus" class="field-note" role="status"></p></details>`}
function readResourcePolicy(){return {...resourceData.policy,auto_programs:$('#resourceAutoPrograms').checked,auto_skills:$('#resourceAutoSkills').checked,package_terms:$('#resourcePackageTerms').checked,source_terms:$('#resourceSourceTerms').checked,allowed_programs:$$('[data-resource-allow]:checked').map(x=>x.dataset.resourceAllow)}}
function renderProgramCards(){if(!$('#resourcePrograms'))return;const q=resourceQuery.toLowerCase();$('#resourcePrograms').innerHTML=resourceData.programs.map(p=>{if(resourceData.execution?.selected.location!=='shared_vm')return p;const g=resourceData.guest,valid=g?.session&&g.session===resourceData.guest_session;const found=valid&&g.programs?.find(x=>x.id===p.id);return {...p,installed:Boolean(found?.installed),inventory_unknown:!valid,version:'',evidence:found?.evidence||'선택 VM 설치 상태 미확인'}}).filter(p=>(resourceFilter==='all'||(resourceFilter==='installed'?p.installed:!p.installed))&&(!q||(p.name+' '+p.description+' '+p.category+' '+(p.keywords||[]).join(' ')).toLowerCase().includes(q))).sort((a,b)=>Number(Boolean(b.installed))-Number(Boolean(a.installed))).map(p=>{const job=resourceData.jobs.find(j=>j.program===p.id&&j.target==='host'&&['queued','running'].includes(j.state));return `<article class="resource-card ${p.installed?'is-installed':''}"><label class="resource-select"><input type="checkbox" aria-label="${esc(p.name)} 설치 선택" data-resource-program="${p.id}" ${resourceSelection.has(p.id)?'checked':''} ${p.installed||job||p.manual||p.environment_support?.supported===false?'disabled':''}></label>${resourceIcon(p.icon)}<div class="resource-card-head"><h3>${esc(p.name)}</h3><span class="resource-state ${p.installed?'installed':''}">${job?resourceJobLabels[job.state]:p.installed?'설치됨':p.inventory_unknown?'설치 미확인':'미설치'}</span></div><p>${esc(p.description)}</p>${p.environment_support?`<p class="field-note"><b>${esc(p.environment_support.label)}</b> · ${esc(p.environment_support.reason)}</p>`:''}${p.cost_label?`<div class="resource-cost"><b>${esc(p.cost_label)}</b><span>${esc(p.cost_note)}</span><a href="${esc(p.cost_source)}" target="_blank" rel="noopener">사용 조건 ↗</a></div>`:''}${p.setup_note&&(!p.installed||['unity','unreal'].includes(p.id))?`<p class="field-note">${esc(p.installed?'이 PC의 설치를 확인했습니다. 현재 모아의 엔진 실행 연동은 미연결입니다.':p.setup_note)}</p>`:''}<small>${esc(p.version||p.category)} · ${esc(p.evidence)}</small><div class="resource-card-actions"><a class="text-link" href="${esc(p.site)}" target="_blank" rel="noopener">공식 사이트 ↗</a>${p.environment_support?.supported===false?`<button class="button subtle small" disabled>설치 미지원</button>`:p.manual&&!p.installed?`<a class="button subtle small" href="${esc(p.site)}" target="_blank" rel="noopener">설치 안내 ↗</a>`:`<button class="button subtle small" data-resource-action="install-one" data-program-id="${p.id}" ${p.installed||job||p.environment_support?.supported===false?'disabled':''}>${p.environment_support?.supported===false?'설치 미지원':job?'설치 중':p.installed?'설치됨':'설치'}</button>`}</div></article>`}).join('')||'<p class="empty">조건에 맞는 프로그램이 없습니다.</p>';$('#resourceSelectedCount').textContent=resourceSelection.size+'개 선택';}
function renderGuestResources(){
 if(resourceTab!=='programs')return;let el=$('#resourceGuest');if(!el){el=document.createElement('section');el.id='resourceGuest';el.className='card resource-guest';$('.resource-install-bar').after(el)}
 const g=resourceData.guest||{},valid=g.session&&g.session===resourceData.guest_session;
 el.innerHTML=`<div class="section-heading"><h2>실제 VM의 프로그램</h2><a class="text-link" href="#settings/environment">VM 설정 ↗</a></div><p class="field-note">${resourceData.guest_network?'현재 VM 네트워크 사용':'현재 VM 네트워크 꺼짐'} · ${valid?'최근 실제 VM 확인 '+esc(ago(g.checked_at)):'설치 상태 미확인 · 다음 VM 업무에서 실행 파일을 확인합니다.'}</p><div class="resource-guest-list">${resourceData.programs.filter(p=>p.guest||resourceData.execution?.selected.os==='windows'||valid&&g.programs?.some(r=>r.id===p.id&&r.installed)).map(p=>{const found=valid?g.programs.find(r=>r.id===p.id):null;return `<div>${resourceIcon(p.icon)}<span><b>${esc(p.name)}</b><small>${found?(found.installed?'VM 실행 파일 확인됨':'VM 실행 파일 없음'):'VM 설치 여부 미확인'}</small></span><button class="button subtle small" data-resource-action="install-guest" data-program-id="${p.id}" ${found?.installed||p.environment_support?.supported===false||p.manual?'disabled':''}>${p.environment_support?.supported===false?'미지원':p.manual?'직접 인증·설치':found?.installed?'설치됨':'VM 설치 예약'}</button></div>`}).join('')}</div><p class="field-note">예약한 설치는 다음 VM 작업이 화면 사용권을 얻었을 때 실행됩니다. 네트워크가 꺼져 있으면 준비 필요로 남습니다. Windows VM은 WinGet 지원 패키지, Linux VM은 Tiny Core 확장 패키지만 설치합니다. 엔진 로그인·라이선스 확인은 직접 진행하세요.</p>`;
}
