let surveyAnswers={tasks:[],engine:'undecided'},surveyRecommendation=null,surveyInfo=null,surveyBusy=false;
function openSetupSurvey(info){surveyInfo=info;surveyAnswers={tasks:info.saved?.tasks||[],engine:info.saved?.engine||'undecided'};surveyRecommendation=null;let d=$('#setupSurvey');if(!d){d=document.createElement('dialog');d.id='setupSurvey';d.className='setup-survey';document.body.append(d);d.addEventListener('cancel',e=>{e.preventDefault();$('[data-survey="skip"]')?.click()})}renderSurveyQuestions();d.setAttribute('aria-labelledby','surveyTitle');d.showModal();d.querySelector('[data-survey-task]')?.focus()}
function surveyFooter(){return '<div class="survey-dismiss"><button class="text-button" data-survey="skip">건너뛰기</button><button class="text-button" data-survey="manual">알아서 할게요</button></div>'}
function renderSurveyQuestions(){const d=$('#setupSurvey');d.innerHTML=`<button class="office-close" data-survey="skip" aria-label="초기 설정 건너뛰기">×</button><p class="eyebrow">MAKE IT YOURS · 1 / 2</p><h2 id="surveyTitle">주로 어떤 일을 하실 건가요?</h2><p class="lead">여러 개 골라도 됩니다. 답변에 맞춰 필요한 준비를 추천합니다.</p><div class="survey-choices">${surveyInfo.tasks.map(t=>`<label><input type="checkbox" data-survey-task="${esc(t.id)}" ${surveyAnswers.tasks.includes(t.id)?'checked':''}><span><b>${esc(t.name)}</b><small>${esc(t.description)}</small></span></label>`).join('')}</div><div id="surveyEngine" class="survey-engine" ${surveyAnswers.tasks.includes('game')?'':'hidden'}><p>사용할 게임 엔진</p>${[['undecided','아직 모르겠어요'],['unity','Unity'],['unreal','Unreal Engine']].map(([id,name])=>`<label><input type="radio" name="surveyEngine" value="${id}" ${surveyAnswers.engine===id?'checked':''}>${name}</label>`).join('')}</div><button class="button survey-next" data-survey="preview">추천 보기 →</button>${surveyFooter()}`}
function renderSurveyRecommendation(rec){surveyRecommendation=rec;const d=$('#setupSurvey');d.innerHTML=`<button class="office-close" data-survey="skip" aria-label="초기 설정 건너뛰기">×</button><p class="eyebrow">READY FOR YOU · 2 / 2</p><h2 id="surveyTitle">이렇게 준비해 보세요.</h2><p class="lead">필요한 항목만 선택하시면 됩니다.</p><h3>프로그램</h3><div class="survey-items">${rec.programs.map(p=>`<label><input type="checkbox" data-survey-program="${esc(p.id)}" ${p.installed?'disabled':'checked'}>${resourceIcon(p.icon)}<span><b>${esc(p.name)}</b><small>${p.installed?'이미 설치됨':p.manual?'공식 설치 안내로 준비':'설치 후보'} · ${esc(p.description)}</small></span></label>`).join('')||'<p class="field-note">별도로 설치할 프로그램을 권장하지 않습니다.</p>'}</div><h3>스킬</h3><div class="survey-items">${rec.skills.map(s=>`<label><input type="checkbox" data-survey-skill="${esc(s.id)}" checked ${s.installed?'disabled':''}>${resourceIcon(s.icon)}<span><b>${esc(s.name)}</b><small>${s.installed?'추가됨 · ':''}${esc(s.description)}</small></span></label>`).join('')}</div><label class="survey-team"><input id="surveyApplyTeam" type="checkbox" ${rec.can_apply_team?'checked':'disabled'}><span><b>${rec.can_apply_team?esc(rec.team.name)+' · '+rec.team.count+'명':'현재 팀 구성을 유지합니다'}</b><small>${rec.can_apply_team?'이 PC 사양에 맞춘 시작 구성입니다.':'기존 이름·프로필·지시 사항을 유지합니다.'}</small></span></label>${rec.game_note?`<p class="field-note">${esc(rec.game_note)}</p>`:''}<p class="survey-note">${esc(rec.note)}</p><div class="survey-apply"><button class="text-button" data-survey="back">← 다시 선택</button><button class="button" data-survey="apply">적용하고 준비하기</button></div>${surveyFooter()}`;d.scrollTop=0}
async function dismissSurvey(action){await api('/api/onboarding',{action});setup.onboarding={...setup.onboarding,needed:false};$('#setupSurvey').close();if(action==='manual')location.hash='resources'}
document.addEventListener('change',event=>{const t=event.target;if(t.dataset.surveyTask){surveyAnswers.tasks=$$('[data-survey-task]:checked').map(el=>el.dataset.surveyTask);$('#surveyEngine').hidden=!surveyAnswers.tasks.includes('game')}if(t.name==='surveyEngine')surveyAnswers.engine=t.value});
document.addEventListener('click',event=>{const open=event.target.closest('[data-survey-open]');if(open){if(resourceData)rememberResourceDraft();busy(open,async()=>openSetupSurvey(await api('/api/onboarding')));return}const b=event.target.closest('[data-survey]');if(!b||surveyBusy)return;surveyBusy=true;busy(b,async()=>{const action=b.dataset.survey;if(action==='skip'||action==='manual'){await dismissSurvey(action);return}if(action==='back'){renderSurveyQuestions();return}if(action==='preview'){renderSurveyRecommendation(await api('/api/onboarding',{action:'preview',...surveyAnswers}));return}if(action==='apply'){const programs=$$('[data-survey-program]:checked').map(el=>el.dataset.surveyProgram),skills=$$('[data-survey-skill]:checked').map(el=>el.dataset.surveySkill),applyTeam=$('#surveyApplyTeam').checked;const saved=await api('/api/onboarding',{action:'apply',...surveyAnswers,programs,skills,apply_team:applyTeam});setup.onboarding={...setup.onboarding,needed:false,saved};surveyInstallSelectionLoaded=true;if(applyTeam){const latest=await api('/api/setup');setup.team=latest.team;teamDraft=structuredClone(latest.team);renderTeam()}$('#setupSurvey').close();resourceSelection=new Set(programs.filter(id=>!surveyRecommendation.programs.find(p=>p.id===id)?.manual));resourceTab='programs';resourceQuery='';resourceFilter='all';if(location.hash==='#resources')await loadResources(true);else location.hash='resources';await refresh();notify('추천 설정을 적용했습니다. 프로그램은 목록에서 확인한 뒤 설치해 주세요.')}}).finally(()=>surveyBusy=false)});

