function openCompanyEditor(){let dialog=$('#companyEditor');if(!dialog){dialog=document.createElement('dialog');dialog.id='companyEditor';dialog.className='company-editor';document.body.append(dialog)}const value=state.company||{};dialog.innerHTML=`<button class="office-close" data-company-close aria-label="닫기">×</button><p class="eyebrow">OUR COMPANY</p><h2>우리 회사</h2><div class="company-preview"><img src="${esc(value.icon_url||'')}" alt="회사 썸네일"><div><button class="button subtle small" data-company-random>랜덤 썸네일</button><label class="company-upload">직접 이미지 선택<input type="file" accept="image/png,image/jpeg,image/webp" data-company-upload></label></div></div><label>회사 이름<input id="companyNameInput" maxlength="60" value="${esc(value.custom_name||'')}" placeholder="${esc((value.workspace||'MOA')+' 컴퍼니')}"></label><p class="field-note">비워두면 Slack 워크스페이스 이름 + 컴퍼니로 표시합니다.</p><button class="button" data-company-save>저장</button><hr><p class="field-note">${esc(value.slack_icon_note||'')}</p><button class="button subtle small" data-company-download>Slack용 이미지 내려받기</button><p class="field-note" id="companyStatus" role="status"></p>`;dialog.showModal()}
document.addEventListener('click',event=>{const t=event.target.closest('[data-company-edit],[data-company-close],[data-company-save],[data-company-random],[data-company-download]');if(!t)return;if(t.hasAttribute('data-company-edit')){openCompanyEditor();return}if(t.hasAttribute('data-company-close')){$('#companyEditor').close();return}if(t.hasAttribute('data-company-download')){busy(t,async()=>{const response=await fetch(state.company.icon_url);if(!response.ok)throw Error('이미지를 내려받지 못했습니다.');const url=URL.createObjectURL(await response.blob()),a=document.createElement('a');a.href=url;a.download='company-icon.png';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)});return}busy(t,async()=>{const random=t.hasAttribute('data-company-random');await api('/api/company',random?{randomize:true}:{name:$('#companyNameInput').value});await refresh();$('#companyEditor .company-preview img').src=state.company.icon_url;$('#companyStatus').textContent='저장했습니다.'})});
document.addEventListener('change',event=>{if(!event.target.matches('[data-company-upload]'))return;const file=event.target.files?.[0];if(!file)return;busy(null,async()=>{if(file.size>1000000)throw Error('1MB 이하 이미지를 선택하세요.');const data=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(file)});await api('/api/company',{image_base64:data.split(',')[1]});await refresh();$('#companyEditor .company-preview img').src=state.company.icon_url;$('#companyStatus').textContent='이미지를 저장했습니다.'})});

function mediaPath(name){return typeof name==='string'&&name.length<240&&!name.includes('\\')&&!name.includes(':')&&!name.split('/').some(p=>!p||p==='.'||p==='..')&&(/^(deliverables|attachments|vm)\//.test(name)||/^workspace\/research\/image\.(jpg|png)$/.test(name))}
function fileSize(n){return Number.isFinite(n)?n>=1048576?(n/1048576).toFixed(1)+' MB':n>=1024?Math.ceil(n/1024)+' KB':n+' B':''}
function mediaCards(tid,files){const unique=[...new Map(files.filter(f=>mediaPath(f.name)).map(f=>[f.name,f])).values()];return '<div class="message-media">'+unique.map(file=>{const href='/api/artifact?'+new URLSearchParams({task:tid,file:file.name}),name=file.label||file.name.split('/').pop(),ext=file.name.split('.').pop().toLowerCase(),image=['png','jpg','jpeg','gif','webp'].includes(ext);return `<article data-media-file="${esc(file.name)}" class="media-card ${image?'media-image':'media-file'}">${image?`<button class="media-image-open" data-media-open="${esc(href)}" data-media-name="${esc(name)}" aria-label="${esc(name)} 크게 보기"><img src="${esc(href)}" alt="${esc(name)}" loading="lazy"></button>`:`<div class="media-file-heading"><span class="media-file-icon">${esc(ext.toUpperCase().slice(0,5))}</span><div><b>${esc(name)}</b><small>${esc(ext.toUpperCase())}${file.bytes!=null?' · '+fileSize(file.bytes):''}</small></div></div>${file.preview?`<pre class="media-text-preview">${esc(file.preview)}</pre>`:''}`}<div class="media-card-footer">${image?`<span>${esc(name)}${file.bytes!=null?' · '+fileSize(file.bytes):''}</span>`:'<span></span>'}<a href="${esc(href)}" target="_blank" rel="noopener" aria-label="${esc(name)} 열기">열기 ↗</a><a href="${esc(href)}" download="${esc(name)}" aria-label="${esc(name)} 다운로드">↓</a></div></article>`}).join('')+'</div>'}
function messageMedia(message,tid){let data={};try{data=JSON.parse(message.content)||{}}catch{}
 let refs=[...(message.kind==='browser_action'&&typeof data.screenshot==='string'?['workspace/'+data.screenshot]:[]),...(Array.isArray(data.images)?data.images:[]),...(Array.isArray(data.files)?data.files:[]),...(Array.isArray(data.received_images)?data.received_images:[]),...(typeof data.path==='string'&&/^research\/image\.(jpg|png)$/.test(data.path)?['workspace/'+data.path]:[])];
 if(message.kind==='handoff'&&!refs.length){const previous=modalMessages.find(m=>m.seq===message.seq-1&&m.kind==='message'&&m.agent===message.agent&&m.recipient===message.recipient);if(previous){try{const body=JSON.parse(previous.content.slice(previous.content.indexOf('{')));refs=[...(Array.isArray(body.images)?body.images:[]),...(Array.isArray(body.files)?body.files:[])]}catch{}}}
 const files=refs.filter(mediaPath).map(name=>artifactInfo?.task_id===tid&&artifactInfo.files?.find(f=>f.name===name)||{name});const shared=files.filter(f=>!f.name.startsWith('vm/')),screens=files.filter(f=>f.name.startsWith('vm/'));return (shared.length?mediaCards(tid,shared):'')+(screens.length?`<details class="media-evidence"><summary>공유한 작업 화면 ${screens.length}장</summary>${mediaCards(tid,screens)}</details>`:'');
}
document.addEventListener('click',event=>{const button=event.target.closest('[data-media-open]');if(!button)return;const href=button.dataset.mediaOpen;if(!href.startsWith('/api/artifact?'))return;let dialog=$('#mediaViewer');if(!dialog){dialog=document.createElement('dialog');dialog.id='mediaViewer';dialog.className='media-viewer';document.body.append(dialog)}dialog.innerHTML=`<form method="dialog"><button aria-label="미리보기 닫기">×</button></form><img src="${esc(href)}" alt="${esc(button.dataset.mediaName)}"><p>${esc(button.dataset.mediaName)}</p>`;dialog.showModal()});
const officeMediaCache=new Map();let officeMediaGeneration=0;
async function fillOfficeMedia(data){const generation=++officeMediaGeneration,area=$('#officeChatMessages');if(!area)return;const targets=[...area.querySelectorAll('[data-office-media-task]')].slice(-8);await Promise.all(targets.map(async target=>{const tid=target.dataset.officeMediaTask;if(!/^[a-f0-9]{12}$/.test(tid))return;const task=state.tasks.find(t=>t.id===tid);if(task&&!['completed','failed'].includes(task.status))return;let cached=officeMediaCache.get(tid);if(!cached||Date.now()-cached.at>10000){try{cached={at:Date.now(),files:(await api('/api/artifacts?'+new URLSearchParams({task:tid}))).files};officeMediaCache.set(tid,cached)}catch{return}}if(generation!==officeMediaGeneration||officeSelected!==data.agent_id||!target.isConnected)return;const files=cached.files.filter(f=>f.kind==='deliverable'||f.name.startsWith('deliverables/'));target.innerHTML=files.length?mediaCards(tid,files):'';}))}

function gitAuthorEmail(agent){return state.project_git?.authors?.[agent.id]||''}
function renderProjectGit(){const value=state.project_git,root=$('#projectGitPanel');if(!value||!root)return;const signature=JSON.stringify([value,state.team?.agents?.map(a=>[a.id,a.name])]);$('#projectGitConnection').textContent=value.connected?'연결됨':'미연결';if(root.dataset.signature===signature)return;root.dataset.signature=signature;$('#projectGitUrl').value=value.url;$('#projectGitBranch').value=value.branch;$('#projectGitAuthors').innerHTML=(state.team?.agents||[]).map(a=>`<label>${esc(a.name)}<input type="text" inputmode="email" data-git-author="${esc(a.id)}" value="${esc(gitAuthorEmail(a))}" maxlength="230"></label>`).join('')}
