document.addEventListener('click',event=>{const button=event.target.closest('[data-project-git],[data-project-git-publish],[data-git-push-now]');if(!button)return;if(button.hasAttribute('data-project-git-publish')){const task=state.tasks.find(t=>t.id===activeTask)||workTasks.find(t=>t.id===activeTask),p=plan(task);let dialog=$('#gitPublishDialog');if(!dialog){dialog=document.createElement('dialog');dialog.id='gitPublishDialog';dialog.className='company-editor';document.body.append(dialog)}dialog.dataset.task=task.id;dialog.innerHTML=`<form method="dialog"><button class="office-close" aria-label="닫기">×</button></form><p class="eyebrow">PUBLISH RESULTS</p><h2>Git에 결과 올리기</h2><p class="field-note">${esc(state.project_git.url)}<br>브랜치: moa/${esc(task.id)}<br>저장 위치: moa-results/${esc(task.id)}</p><label>커밋 담당자<select id="gitPublishAuthor">${p.agents.map(a=>`<option value="${esc(a.id)}" ${a.id===p.assignment.developer?'selected':''}>${esc(a.name)} · ${esc(gitAuthorEmail(a))}</option>`).join('')}</select></label><p class="field-note">선택한 담당자의 이름·이메일을 author와 committer에 함께 기록합니다. Git 저장소에 공개될 수 있습니다.</p><button class="button" data-git-push-now>커밋하고 업로드</button><p id="gitPublishStatus" class="field-note" role="status"></p>`;dialog.showModal();return}if(button.hasAttribute('data-git-push-now')){busy(button,async()=>{const dialog=$('#gitPublishDialog');$('#gitPublishStatus').textContent='커밋·업로드 중…';try{const result=await api('/api/git',{action:'publish',task_id:dialog.dataset.task,agent_id:$('#gitPublishAuthor').value});$('#gitPublishStatus').textContent='업로드 완료 · '+result.author+' <'+result.email+'> · '+result.commit.slice(0,10);button.disabled=true}catch(error){$('#gitPublishStatus').textContent='완료 여부를 확인하지 못했습니다. '+error.message;throw error}});return}busy(button,async()=>{const action=button.dataset.projectGit;$('#projectGitStatus').textContent=action==='connect'?'저장소 연결을 확인하고 있습니다…':'설정을 저장하고 있습니다…';try{await api('/api/git',{action:'save',...projectGitValues()});if(action==='connect')await api('/api/git',{action:'connect'});await refresh();$('#projectGitStatus').textContent=action==='connect'?'저장소 연결을 확인했습니다.':'저장했습니다.'}catch(error){$('#projectGitStatus').textContent=error.message;throw error}})});

