// Request history preserves every receipt independently of the current composer.
const requestReceipts=new Map();let selectedRequestId='',requestDetailVersion=0;
function rememberRequest(value){if(!value?.id)return;requestReceipts.set(value.id,{...requestReceipts.get(value.id),...value});renderRequestHistory()}
function allRequests(){for(const r of state.leader_requests||[]){const cached=requestReceipts.get(r.id);if(!cached||(r.updated||0)>=(cached.updated||0))requestReceipts.set(r.id,{...cached,...r})}return [...requestReceipts.values()].sort((a,b)=>(b.created||0)-(a.created||0))}
function requestState(r){const task=state.tasks.find(t=>t.id===r.task_id);return task?statuses[task.status]||task.status:({queued:'접수 대기',planning:'처리 중',delegated:'배정됨',replied:'답변 완료',failed:'확인 필요'}[r.state]||'접수됨')}
function renderRequestHistory(){const host=$('#requestPreview');if(!host)return;const rows=allRequests();host.hidden=!rows.length;const html='<button type="button" class="request-history-all" data-request-history title="보낸 요청과 답변 보기" aria-label="보낸 요청 '+rows.length+'건 보기">보낸 요청 <span>'+rows.length+'</span></button>';if(host.innerHTML!==html)host.innerHTML=html;if($('#requestHistoryDialog')?.open){renderRequestHistoryList();const r=requestReceipts.get(selectedRequestId),meta=$('#requestHistoryDetail .request-detail-meta');if(r&&meta){meta.textContent=(r.leader_name||'팀원')+' · '+requestState(r);const brief=$('#requestRefinement'),html=requestRefinementHtml(r);if(brief&&brief.innerHTML!==html)brief.innerHTML=html}}}
function renderRequestHistoryList(){const host=$('#requestHistoryList'),rows=allRequests();const html=rows.map(r=>`<button type="button" data-request-id="${esc(r.id)}" aria-current="${r.id===selectedRequestId}"><strong>${esc(r.title||'요청 내용 보기')}</strong><small>${esc(r.leader_name||'팀원')} · ${esc(requestState(r))}${r.parent_request_id?' · 추가 요청':''}</small></button>`).join('')||'<p>아직 보낸 요청이 없습니다.</p>';if(host.innerHTML!==html)host.innerHTML=html}
async function openRequestHistory(id){const rows=allRequests(),dialog=$('#requestHistoryDialog');selectedRequestId=id||rows[0]?.id||'';if(!dialog.open)dialog.showModal();renderRequestHistoryList();const version=++requestDetailVersion;let r=requestReceipts.get(selectedRequestId);renderRequestDetail(r);if(!selectedRequestId)return;try{const result=await api('/api/leader/request?id='+encodeURIComponent(selectedRequestId));if(version!==requestDetailVersion)return;rememberRequest(result);renderRequestDetail(result)}catch(e){if(version===requestDetailVersion&&!r)$('#requestHistoryDetail').textContent=e.message}}
function requestRefinementHtml(r){const fields={goal:'목적',requirements:'요구사항',deliverables:'결과물',acceptance:'완료 조건',constraints:'제약 사항',unknowns:'미확인 사항',changes:'정리한 내용'};if(!r?.refinement)return '<p class="request-refinement-pending">'+(['queued','planning'].includes(r?.state)?'리더가 요청을 정리하면 이곳에 표시됩니다.':'이 요청에는 별도의 리더 정리본이 없습니다.')+'</p>';return '<h3>리더가 정리한 요청 <small>'+esc(r.refinement_author||'리더')+'</small></h3><dl class="request-refinement">'+Object.entries(fields).map(([key,label])=>'<div><dt>'+label+'</dt><dd>'+esc(r.refinement[key]||(key==='changes'?'원문을 보존하고, 요청을 목적·요구사항·결과물·완료 조건·제약·미확인 사항으로 나누었습니다. 각 항목에서 정리 결과를 확인할 수 있습니다.':'미확인 — 원문에 명시되지 않음'))+'</dd></div>').join('')+'</dl>'}
function renderRequestDetail(r){const host=$('#requestHistoryDetail');if(!r){host.innerHTML='<p>확인할 요청을 선택해 주세요.</p>';return}host.innerHTML=`<div class="request-detail-meta">${esc(r.leader_name||'팀원')} · ${esc(requestState(r))}</div><h3>내가 보낸 요청</h3><div class="request-original">${esc(r.title||'원문을 불러오는 중입니다.')}</div><section id="requestRefinement">${requestRefinementHtml(r)}</section>${r.answer?'<h3>팀원 답변</h3><div class="request-answer">'+esc(r.answer)+'</div>':''}${r.error?'<p class="request-error">'+esc(r.error)+'</p>':''}${r.task_id?'<button class="button subtle" data-request-task="'+esc(r.task_id)+'">작업 진행·결과 보기 ↗</button>':''}<form id="requestFollowup"><label for="requestFollowupText">이 요청에 이어서 추가로 요청하기</label><textarea id="requestFollowupText" rows="3" placeholder="추가할 내용을 입력해 주세요." required></textarea><button class="button" type="submit">추가 요청 보내기 ↑</button><p class="field-note" id="requestFollowupStatus" role="status"></p></form>`}
document.addEventListener('click',event=>{const node=event.target.closest?.('[data-request-id],[data-request-history],[data-request-close],[data-request-task]');if(!node)return;if(node.hasAttribute('data-request-close')){$('#requestHistoryDialog').close();return}if(node.dataset.requestTask){$('#requestHistoryDialog').close();openTask(node.dataset.requestTask);return}openRequestHistory(node.dataset.requestId)});
document.addEventListener('submit',event=>{if(event.target.id!=='requestFollowup')return;event.preventDefault();const input=$('#requestFollowupText'),title=input.value.trim(),parent=selectedRequestId;if(!title)return;const button=event.target.querySelector('button');busy(button,async()=>{const payload=gatherTask(),result=await api('/api/tasks',{...payload,title,leader_first:true,parent_request_id:parent,request_key:crypto.randomUUID()});result.title=result.title||title;rememberRequest(result);activeLeaderRequest=result.id;showLeaderReceipt(result);pollLeaderReceipt(result.id);await openRequestHistory(result.id);notify('추가 요청을 전달했습니다.');refresh().catch(()=>{})})});

