 const latest=state.tasks.filter(t=>t.status==='completed'&&t.timing?.recorded&&Number.isFinite(t.timing.elapsed_seconds)).sort((a,b)=>(b.timing.finished_at||b.created)-(a.timing.finished_at||a.created))[0];
 el.hidden=!latest;if(!latest)return;
 el.textContent='최근 '+(latest.timing.estimated?'약 ':'')+formatTaskDuration(latest.timing.elapsed_seconds);
