/* Continuous goal planning and morning review. */
let goalSubmission=null;
async function registerGoal(title,hours,max_tasks){const data={action:'create',title,hours,max_tasks},signature=JSON.stringify(data);if(!goalSubmission||goalSubmission.signature!==signature)goalSubmission={signature,key:crypto.randomUUID()};const pending=goalSubmission,result=await api('/api/goals',{...data,request_key:pending.key});if(goalSubmission===pending)goalSubmission=null;return result}
function taskHeadline(task){for(const g of state.continuous_goals?.goals||[]){const item=g.items.find(i=>i.task_id===task.id),parent=item&&g.items.find(i=>i.id===item.parent_item);if(parent)return ('수정 · '+parent.title.split('\n')[0]).slice(0,180)}return String(task.title||'작업 결과').split('\n')[0].slice(0,180)}
function installGoalsUI(){
 const nav=document.createElement('a');nav.href='#goals';nav.dataset.page='goals';nav.innerHTML=icon('spark')+'<span>지속 목표</span>';$('.sidebar nav').insertBefore(nav,$('.sidebar [data-page="work"]'));
 const page=document.createElement('section');page.id='page-goals';page.className='page';page.hidden=true;
 page.innerHTML=`<div class="page-heading"><div><p class="eyebrow">WORK WHILE YOU REST</p><h1>목표를 맡기고, 결과를 검토하세요.</h1><p class="lead">리더가 일을 나누고 검증합니다. 완료된 결과는 아침에 한곳에서 확인하세요.</p></div></div><section class="card goal-create"><label for="goalTitle">지속할 목표</label><textarea id="goalTitle" rows="3" maxlength="6000" placeholder="예: 프로젝트의 접근성을 개선하고 화면별 검증 결과를 정리해 주세요."></textarea><div class="goal-create-footer"><label>실행 시간<select id="goalHours"><option value="8">8시간</option><option value="24" selected>24시간</option><option value="72">3일</option><option value="168">7일</option></select></label><label>최대 작업 수<input id="goalLimit" type="number" min="1" max="100" value="20"></label><button class="button" data-goal-create>목표 시작 ↗</button></div><p class="field-note">작업 중에는 자동 절전을 방지합니다. 화면은 꺼져도 됩니다. 직접 절전·종료하면 작업이 멈춥니다. 실제 실행 환경은 팀 설정을 따르며, 자동 Git 게시·배포는 보류합니다.</p></section><p id="goalGlobalStatus" role="status" class="field-note"></p><div id="goalList"></div>`;
 $('#main').append(page);
}
const goalStates={active:'진행 중',paused:'일시 중지',stopped:'종료',needs_review:'검토 필요',completed:'검토 완료'};
function renderGoals(){
 const host=$('#goalList');if(!host)return;const data=state.continuous_goals||{goals:[]};
 $('#goalGlobalStatus').textContent=data.paused?'전체 업무가 일시 중지되어 있습니다. 상단의 업무 재개를 눌러야 진행됩니다.':'완료 결과를 기다리지 않고 다음 업무를 진행합니다. 결과를 열어 확인한 뒤 승인하거나 수정을 요청하세요.';
 if(data.scheduler?.alive===false&&data.goals.some(g=>g.state==='active'))$('#goalGlobalStatus').textContent+=' · 자동 진행 서비스 연결 확인 필요';if(data.scheduler?.error)$('#goalGlobalStatus').textContent+=' · '+data.scheduler.error;
 if(data.power_error)$('#goalGlobalStatus').textContent+=' · '+data.power_error;else if(data.keep_awake)$('#goalGlobalStatus').textContent+=' · 자동 절전 방지 중';
 const signature=JSON.stringify(data,(key,value)=>['updated','timing','request_key','last_loop_at'].includes(key)?undefined:value);if(host.dataset.signature===signature){for(const g of data.goals)for(const item of g.items){const node=host.querySelector('[data-goal-duration="'+item.id+'"]'),seconds=item.task?.timing?.elapsed_seconds;if(node)node.textContent=seconds!=null?' · '+Math.round(seconds)+'초':'';}return;}
 // Keep a user's review note/focus during real-time updates.
 const drafts=Object.fromEntries([...host.querySelectorAll('[data-goal-feedback]')].map(n=>[n.dataset.goalFeedback,n.value]));
 const focus=document.activeElement?.dataset.goalFeedback;const selection=focus?[document.activeElement.selectionStart,document.activeElement.selectionEnd]:null;
 host.dataset.signature=signature;host.innerHTML=data.goals.map(g=>`<section class="card goal-card"><header><div><span class="tag">${esc(goalStates[g.state]||g.state)}</span><h2>${esc(g.title.length>180?g.title.slice(0,180)+"…":g.title)}</h2>${g.title.length>180?`<details class="goal-brief"><summary>목표 전체 보기</summary><p>${esc(g.title)}</p></details>`:""}<p class="field-note">${g.items.length} / ${g.max_tasks}개 · ${esc(new Date(g.deadline*1000).toLocaleString('ko-KR'))}까지</p></div><div class="inline-actions">${g.state==='active'?`<button class="text-button" data-goal-id="${g.id}" data-goal-control="pause">일시 중지</button>`:['paused','needs_review'].includes(g.state)?`<button class="text-button" data-goal-id="${g.id}" data-goal-control="resume">계속 진행</button>`:''}${!['completed','stopped'].includes(g.state)?`<button class="text-button" data-goal-id="${g.id}" data-goal-control="stop">종료</button>`:''}</div></header>${g.reason?`<p class="goal-reason">${esc(g.reason)}</p>`:''}${g.progress?`<details class="field-note"><summary>리더 진행 메모</summary><p>${esc(g.progress)}</p></details>`:''}<div class="goal-results">${g.items.map(item=>{const q=item.task?.quality_review,t=item.task?.timing?.elapsed_seconds,parent=g.items.find(p=>p.id===item.parent_item),shortTitle=(parent?'수정 · '+parent.title.split('\n')[0]:item.title.split('\n')[0]).slice(0,160);return `<article class="goal-result"><div class="goal-result-heading"><span class="goal-order">${item.ordinal}</span><div><h3>${esc(shortTitle)}</h3>${item.title!==shortTitle?`<details class="goal-brief"><summary>업무 내용 보기</summary><p>${esc(item.title)}</p></details>`:""}<p class="field-note">${esc(item.state==='ready'?'결과 준비됨':item.state==='failed'?'확인 필요':item.state==='queued'?'접수 대기':item.task?.wait_reason==='resource_setup'?'설치 준비 대기':statuses[item.task?.status]||'리더에게 전달됨')}<span data-goal-duration="${item.id}">${t!=null?' · '+Math.round(t)+'초':''}</span>${q?' · 검토 '+q.review_count+'회 · 반려 '+q.rejection_count+'회':''}</p></div>${item.task_id?`<button class="button subtle small" data-task="${item.task_id}" ${item.state==='ready'?'data-completion-toast="true"':''}>결과·로그 보기 ↗</button>`:''}</div>${item.error?`<p class="goal-reason">${esc(item.error)}</p>`:''}${item.state==='ready'&&item.review==='pending'?`<div class="goal-review"><input data-goal-feedback="${item.id}" aria-label="수정 요청 내용" maxlength="2000" placeholder="수정이 필요하면 내용을 적어 주세요" value="${esc(drafts[item.id]||'')}"><button class="button subtle small" data-goal-review="changes_requested" data-goal-item="${item.id}">수정 요청</button><button class="button small" data-goal-review="approved" data-goal-item="${item.id}">확인·승인 ✓</button></div>`:item.review!=='pending'?`<p class="field-note">${item.review==='approved'?'승인됨':'수정 요청됨'} ${esc(item.feedback)}</p>`:''}</article>`}).join('')||'<p class="field-note">리더가 첫 업무를 준비합니다. 전체 업무 일시 중지·VM 설치 상태도 확인해 주세요.</p>'}</div></section>`).join('')||'<section class="card goal-empty"><h2>밤새 진행할 목표를 남겨 주세요.</h2><p>업무 분배 → 실제 실행 → 반복 검증 → 결과 보관</p><p class="field-note">프롬프트에서 /goal 뒤에 목표를 적어 시작할 수도 있습니다.</p></section>';
 if(focus){const input=[...host.querySelectorAll('[data-goal-feedback]')].find(n=>n.dataset.goalFeedback===focus);input?.focus();if(input&&selection)input.setSelectionRange(...selection);}
}
document.addEventListener('click',event=>{
 const b=event.target.closest('[data-goal-create],[data-goal-control],[data-goal-review]');if(!b)return;
 busy(b,async()=>{let data;if(b.hasAttribute('data-goal-create'))data={action:'create',title:$('#goalTitle').value,hours:Number($('#goalHours').value),max_tasks:Number($('#goalLimit').value)};
 else if(b.dataset.goalControl)data={action:b.dataset.goalControl,id:b.dataset.goalId};
 else data={action:'review',id:b.dataset.goalItem,verdict:b.dataset.goalReview,feedback:[...document.querySelectorAll('[data-goal-feedback]')].find(n=>n.dataset.goalFeedback===b.dataset.goalItem)?.value||''};
 if(data.action==='create')await registerGoal(data.title,data.hours,data.max_tasks);else await api('/api/goals',data);if(data.action==='create')$('#goalTitle').value='';await refresh();notify(data.action==='create'?'지속 목표를 등록했습니다.':'저장했습니다.');});
});
installGoalsUI();


const windowsInstallButton=document.createElement('button');windowsInstallButton.className='button subtle small';windowsInstallButton.textContent='Windows 설치 모드 시작 · 2GB';windowsInstallButton.type='button';windowsInstallButton.addEventListener('click',()=>busy(windowsInstallButton,async()=>{await api('/api/vm/control',{action:'start-installation'});await refresh();notify('Windows 설치 전용 모드를 시작했습니다. VM 화면에서 설치 단계를 확인하세요.');}));$('[data-action="create-windows-disk"]')?.after(windowsInstallButton);

boot();
